"""Arte das cartas do Ticker Battle (recortadas da cartela enviada, WebP em base64). Cartas sem arte aqui usam o visual gerado por código."""
_A = {
 "PETR4": "",
 "VALE3": "",
 "ITUB4": "",
 "BBDC4": "",
 "ABEV3": "",
 "WEGE3": "",
 "EMBR3": "",
 "UGPA3": "",
 "BRKM5": "",
 "BBAS3": "",
 "SANB11": "",
 "MGLU3": "",
 "TIMS3": "",
 "SUZB3": "",
 "B3SA3": "",
 "CPFE3": "",
}


def tem(tk: str) -> bool:
    return tk in _A


def uri(tk: str) -> str:
    return "data:image/webp;base64," + _A[tk] if tk in _A else ""
